/// <reference types="react" />
import { Table } from '@tanstack/react-table';
import { TableRowType } from '../../types/table.types';
export interface ICheckboxHeaderCellProps<TData extends TableRowType> {
    /**
     * Table instance from Tanstack Table
     */
    table: Table<TData>;
    /**
     * Callback when header selection changes
     * Provides the selection state and affected rows
     */
    onHeaderSelectionChange: (isSelected: boolean, rows: TData[]) => void;
    /**
     * Optional prop to disable checkbox
     * @default false
     */
    disabled?: boolean;
    /**
     * Optional className to add to the checkbox container
     */
    className?: string;
}
/**
 * A header cell renderer that displays a checkbox for selecting/deselecting all rows
 *
 * @example
 * // Basic usage - column definition
 * {
 *   id: 'select',
 *   header: ({ table }) => (
 *     <CheckboxHeaderCell table={table} onHeaderSelectionChange={...} />
 *   ),
 *   cell: ({ row }) => (
 *     <CheckboxCell cell={{ row }} />
 *   ),
 *   size: 40,
 * }
 *
 * @remarks
 * If you use header selection in a controlled way, you must provide the `onHeaderSelectionChange` callback. Omitting it will cause the component to switch between controlled and uncontrolled modes, which is not supported and will log a warning in development mode.
 */
export declare const CheckboxHeaderCell: <TData extends {
    readonly id: string | number;
}>({ table, onHeaderSelectionChange, disabled, className, }: ICheckboxHeaderCellProps<TData>) => JSX.Element;
